import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useOneAtATime } from '../../query/useOneAtATime';
import { peopleKey } from '../people/people';
import type { Person } from '../people/people';
import { usePersonError } from '../people/personError';
import { useCurrentSheet, useCurrentUser } from '../session/session';

// Whether the person is retired and from when, and the date and button that retire them (a blank
// date is the sheet's today). A retired person's claims keep counting; one dated after is refused.
export function PersonRetire({ person }: { person: Person }) {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const [from, setFrom] = useState('');
  const [, setError] = usePersonError(person.id);
  const queryClient = useQueryClient();
  const once = useOneAtATime();

  const retire = useMutation({
    mutationFn: (date: string) =>
      postJson<Person>(
        `/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/retire?user=${encodeURIComponent(user)}`,
        { from: date },
      ),
    onSuccess: async () => {
      setFrom('');
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheet) });
    },
    onError: () => setError('The person could not be retired.'),
  });

  const submit = () => {
    setError('');
    const date = from.trim();
    if (date && !/^\d{4}-\d{2}-\d{2}$/.test(date)) {
      setError('Type a date as yyyy-mm-dd.');
      return;
    }
    once(() => retire.mutateAsync(date));
  };

  return (
    <td>
      <span data-testid="person-retired">{person.retired ? 'yes' : 'no'}</span>{' '}
      <span data-testid="person-retired-from">{person.retiredFrom ?? ''}</span>{' '}
      <input
        data-testid="person-retire-date"
        placeholder="yyyy-mm-dd"
        value={from}
        onChange={(e) => {
          setFrom(e.target.value);
          setError('');
        }}
      />
      <button type="button" data-testid="person-retire" disabled={retire.isPending} onClick={submit}>
        Retire
      </button>
    </td>
  );
}
import { HomeMain } from '../../slots/defs/homeMain';
import { PersonColumnHeads, PersonColumns } from '../../slots/defs/personColumns';
import { PersonRetire } from './PersonRetire';
import { ShowRetired } from './ShowRetired';

export const contributions = [
  HomeMain.fill({ order: 17, Component: ShowRetired }),
  PersonColumnHeads.fill({ order: 18, Component: () => <th>Retired</th> }),
  PersonColumns.fill({ order: 18, Component: PersonRetire }),
];
import { useShowRetired } from '../people/people';
import { useCurrentSheet, useCurrentUser } from '../session/session';

// The toggle that lists retired people too; off when the screen is first opened.
export function ShowRetired() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const [on, setOn] = useShowRetired();

  if (!user || !sheet) return null;

  return (
    <label>
      <input
        type="checkbox"
        data-testid="show-retired"
        checked={on}
        onChange={(e) => setOn(e.target.checked || undefined)}
      />{' '}
      Show retired
    </label>
  );
}
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { claimed, useClaims } from './claims';

// The sheet's claimed-total: everyone's claims added up.
export function ClaimedTotal() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const claims = useClaims();

  if (!user || !sheet) return null;

  return (
    <p>
      Claimed total: <strong data-testid="rollup-claimed-total">{claimed(claims.data ?? [])}</strong>
    </p>
  );
}
import { useClaims } from '../claims/claims';
import { usePeople } from '../people/people';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { useSheetToday } from '../session/sheetToday';
import { personDue, total, useRates } from './rates';

// The sheet's due-total: everyone's due-total added up, skipping those that are n/a.
export function DueTotal() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const people = usePeople().data ?? [];
  const claims = useClaims().data ?? [];
  const rates = useRates().data ?? [];
  const today = useSheetToday();

  if (!user || !sheet) return null;

  const dues = people.map((p) => personDue(claims.filter((c) => c.personId === p.id), rates, p.grade, today));
  return (
    <p>
      Due total: <strong data-testid="rollup-due-total">{total(dues)}</strong>
    </p>
  );
}
import { useClaims } from '../claims/claims';
import type { Person } from '../people/people';
import { useSheetToday } from '../session/sheetToday';
import { personDue, useRates } from './rates';

// A person's due-total: the figures of their claims that count, added up; n/a when their grade has no
// rate on the sheet's today, unless a settled or stated claim keeps a figure.
export function PersonDueTotal({ person }: { person: Person }) {
  const rates = useRates().data ?? [];
  const today = useSheetToday();
  const claims = (useClaims().data ?? []).filter((c) => c.personId === person.id);
  return <td data-testid="person-due-total">{personDue(claims, rates, person.grade, today)}</td>;
}
import type { Person } from '../people/people';
import { claimed, useClaims } from './claims';

// What a person has claimed: the sum of their claims' amounts.
export function PersonClaimed({ person }: { person: Person }) {
  const claims = (useClaims().data ?? []).filter((c) => c.personId === person.id);
  return <td data-testid="person-claimed">{claimed(claims)}</td>;
}
import { defineSlot } from '../Slot';
import type { Person } from '../../features/people/people';

/** Extra column headers of the people table: each contribution renders its own <th>. */
export const PersonColumnHeads = defineSlot('people.columnHeads');

/** Extra cells of a person's row, in the same order as PersonColumnHeads: each renders its own <td>. */
export const PersonColumns = defineSlot<{ person: Person }>('people.columns');

